"use strict";

// Algorithm adapted from EffectCraft (MIT OR Apache-2.0).
//
// CC Page Turn: analytic cylinder page curl of the layer in a single
// fragment shader (no simulation history; output depends only on the
// input, properties and layer size). Only the uniforms, properties and
// per-frame updates below are unique to this effect; loading, bundling
// and disposal come from ZoidiumPluginApis.defineFilter.
ZoidiumPluginApis.defineFilter.call(this, {
  displayName: "CC Page Turn",
  fragShaderUrl: "/plugins/native-fx/shaders/fx_ccpageturn.glsl",
  uniforms: {
    uvScale: { type: "v2", value: new THREE.Vector2(1, 1) },
    resolution: { type: "v2", value: new THREE.Vector2(1, 1) },
    foldPos: { type: "v2", value: new THREE.Vector2(0.7, 0.7) },
    foldDir: { type: "f", value: 315 },
    foldRadius: { type: "f", value: 20 },
    lightDir: { type: "f", value: -45 },
    renderMode: { type: "f", value: 0 },
    backOpacity: { type: "f", value: 0.75 },
    paperColor: { type: "v3", value: new THREE.Vector3(1, 1, 1) },
    backSource: { type: "f", value: 0 },
  },
  properties: {
    enabled: {
      dynamic: true,
      name: "Enabled",
      type: PZ.property.type.OPTION,
      value: 1,
      items: "off;on",
    },
    foldPosition: {
      dynamic: true,
      group: true,
      objects: [
        {
          dynamic: true,
          name: "Fold Position.X",
          type: PZ.property.type.NUMBER,
          value: 0.7,
          min: 0,
          max: 1,
          step: 0.01,
          decimals: 3,
        },
        {
          dynamic: true,
          name: "Fold Position.Y",
          type: PZ.property.type.NUMBER,
          value: 0.7,
          min: 0,
          max: 1,
          step: 0.01,
          decimals: 3,
        },
      ],
      name: "Fold Position",
      type: PZ.property.type.VECTOR2,
    },
    foldDirection: {
      dynamic: true,
      name: "Fold Direction",
      type: PZ.property.type.NUMBER,
      value: 315,
      max: 360,
      min: -360,
      step: 1,
      decimals: 1,
    },
    foldRadius: {
      dynamic: true,
      name: "Fold Radius",
      type: PZ.property.type.NUMBER,
      value: 20,
      max: 1000,
      min: 0,
      step: 1,
      decimals: 1,
    },
    lightDirection: {
      dynamic: true,
      name: "Light Direction",
      type: PZ.property.type.NUMBER,
      value: -45,
      max: 360,
      min: -360,
      step: 1,
      decimals: 1,
    },
    render: {
      dynamic: true,
      name: "Render",
      type: PZ.property.type.OPTION,
      value: 0,
      items: "Front & Back Page;Back Page;Front Page",
    },
    backSource: {
      dynamic: true,
      name: "Back Page",
      type: PZ.property.type.OPTION,
      value: 0,
      items: "Mirrored Layer;Paper Color",
    },
    backPageOpacity: {
      dynamic: true,
      name: "Back Opacity",
      type: PZ.property.type.NUMBER,
      value: 75,
      max: 100,
      min: 0,
      step: 1,
      decimals: 0,
    },
    paperColor: {
      dynamic: true,
      name: "Paper Color",
      type: PZ.property.type.COLOR,
      value: [1, 1, 1],
    },
  },
  update(frame) {
    if (!this.pass) return;
    this.pass.enabled = this.properties.enabled.get(frame) === 1;
    var uniforms = this.pass.uniforms;
    var fold = this.properties.foldPosition.get(frame);
    uniforms.foldPos.value.set(Number(fold[0]) || 0, Number(fold[1]) || 0);
    uniforms.foldDir.value = Number(this.properties.foldDirection.get(frame)) || 0;
    uniforms.foldRadius.value = Math.max(0, Number(this.properties.foldRadius.get(frame)) || 0);
    uniforms.lightDir.value = Number(this.properties.lightDirection.get(frame)) || 0;
    uniforms.renderMode.value = Number(this.properties.render.get(frame)) || 0;
    uniforms.backSource.value = Number(this.properties.backSource.get(frame)) || 0;
    var opacity = Number(this.properties.backPageOpacity.get(frame));
    if (!Number.isFinite(opacity)) opacity = 75;
    uniforms.backOpacity.value = Math.min(1, Math.max(0, opacity / 100));
    var paper = this.properties.paperColor.get(frame);
    uniforms.paperColor.value.set(Number(paper[0]) || 0, Number(paper[1]) || 0, Number(paper[2]) || 0);
  },
});

"use strict";

// Algorithm adapted from EffectCraft (MIT OR Apache-2.0).
//
// CC Pixel Polly: the layer breaks into a grid of polygons/squares that fly
// apart under force and gravity with spin. Motion is analytic in time
// (position = f(time since start), no simulation history), so random-order
// evaluation gives identical pixels. Pieces render as one merged triangle
// mesh in a single draw call (bounded piece count); the vertex data is
// recomputed deterministically from the properties and the frame each
// render. Before the start time the input passes through exactly.

var pollyEffect = this;

var pollyMath = (function loadPollyMath() {
  var getAsset = pollyEffect && pollyEffect._zoidiumGetAsset;
  var apis = typeof ZoidiumPluginApis !== "undefined" ? ZoidiumPluginApis : null;
  var createRequire = apis && apis.modules && apis.modules.createRequire;
  if (typeof getAsset !== "function" || typeof createRequire !== "function") {
    throw new Error("CC Pixel Polly needs its bundle math (this._zoidiumGetAsset and ZoidiumPluginApis.modules.createRequire).");
  }
  var loader = createRequire(getAsset, { root: "./plugins/native-fx/", scope: {} });
  return loader("./effects/fxtrans-math.js");
})();

var POLLY_MAX_PIECES = 8192;

var POLLY_VERT = [
  "varying vec2 vLuv;",
  "varying vec2 vCuv;",
  "varying float vShade;",
  "attribute vec2 aCenter;",
  "attribute float aShade;",
  "void main() {",
  "  vLuv = uv;",
  "  vCuv = aCenter;",
  "  vShade = aShade;",
  "  gl_Position = vec4(position.xy, 0.0, 1.0);",
  "}",
].join("\n");

var POLLY_FRAG = [
  "precision highp float;",
  "uniform sampler2D tDiffuse;",
  "uniform vec2 uvScale;",
  "uniform float flatMode;",
  "varying vec2 vLuv;",
  "varying vec2 vCuv;",
  "varying float vShade;",
  "void main() {",
  "  if (vLuv.x < 0.0 || vLuv.x > 1.0 || vLuv.y < 0.0 || vLuv.y > 1.0) {",
  "    gl_FragColor = vec4(0.0);",
  "    return;",
  "  }",
  "  if (flatMode > 0.5) {",
  "    if (vCuv.x < 0.0 || vCuv.x > 1.0 || vCuv.y < 0.0 || vCuv.y > 1.0) {",
  "      gl_FragColor = vec4(0.0);",
  "      return;",
  "    }",
  "    vec4 c = texture2D(tDiffuse, vCuv * uvScale);",
  "    if (c.a <= 0.0001) {",
  "      gl_FragColor = vec4(0.0);",
  "      return;",
  "    }",
  "    gl_FragColor = vec4(c.rgb / c.a * vShade * c.a, c.a);",
  "  } else {",
  "    vec4 texel = texture2D(tDiffuse, vLuv * uvScale);",
  "    gl_FragColor = vec4(texel.rgb * vShade, texel.a);",
  "  }",
  "}",
].join("\n");

function pollyNumber(value, fallback) {
  var number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

(function buildPolly() {
  var effect = pollyEffect;

  effect.defaultName = "CC Pixel Polly";
  effect.propertyDefinitions = {
    enabled: {
      dynamic: true,
      name: "Enabled",
      type: PZ.property.type.OPTION,
      value: 1,
      items: "off;on",
    },
    force: {
