  "  float alpha = base.a + echo.a - base.a * echo.a;",
  "  vec3 blend = 1.0 - (1.0 - straightColor(base)) * (1.0 - straightColor(echo));",
  "  vec3 rgb = base.rgb * (1.0 - echo.a) +",
  "    echo.rgb * (1.0 - base.a) + blend * base.a * echo.a;",
