      name: "Opacity",
      type: PZ.property.type.NUMBER,
      value: 50,
      max: 100,
      min: 0,
      step: 1,
      decimals: 0,
    },
    lightSource: {
      dynamic: true,
      group: true,
      objects: [
        {
          dynamic: true,
          name: "Light Source.X",
          type: PZ.property.type.NUMBER,
          value: 0.3,
          min: 0,
          max: 1,
          step: 0.01,
          decimals: 3,
        },
        {
          dynamic: true,
          name: "Light Source.Y",
          type: PZ.property.type.NUMBER,
          value: 0.2,
          min: 0,
          max: 1,
          step: 0.01,
          decimals: 3,
        },
      ],
      name: "Light Source",
      type: PZ.property.type.VECTOR2,
    },
    projectionDistance: {
      dynamic: true,
      name: "Projection Distance",
      type: PZ.property.type.NUMBER,
      value: 10,
      max: 1000,
      min: 0,
      step: 0.5,
      decimals: 1,
    },
    softness: {
      dynamic: true,
      name: "Softness",
      type: PZ.property.type.NUMBER,
      value: 0,
      max: 1000,
      min: 0,
      step: 0.5,
      decimals: 1,
    },
    render: {
      dynamic: true,
      name: "Render",
      type: PZ.property.type.OPTION,
      value: 0,
      items: "Regular;Glass Edge",
    },
    colorInfluence: {
      dynamic: true,
      name: "Color Influence",
      type: PZ.property.type.NUMBER,
      value: 0,
      max: 100,
      min: 0,
      step: 1,
      decimals: 0,
    },
    shadowOnly: {
      dynamic: true,
      name: "Shadow Only",
      type: PZ.property.type.OPTION,
      value: 0,
      items: "off;on",
    },
  },
  update(frame) {
    if (!this.pass) return;
    this.pass.enabled = this.properties.enabled.get(frame) === 1;
    var uniforms = this.pass.uniforms;
    function num(value, fallback) {
      var n = Number(value);
